INSERT INTO project_directory (project_id, workspace_id, board_id, name, payload, router_time, time_basis, origin_installation, origin_machine, import_digest) VALUES (json_extract(?1, '$.record.envelope.id'), json_extract(?1, '$.record.envelope.scope.workspace'), json_extract(?1, '$.record.board'), json_extract(?1, '$.record.title'), ?1, ?2, ?3, ?4, ?5, ?6) ON CONFLICT(project_id) DO UPDATE SET workspace_id = excluded.workspace_id, board_id = excluded.board_id, name = excluded.name, payload = excluded.payload, router_time = excluded.router_time, time_basis = excluded.time_basis, origin_installation = excluded.origin_installation, origin_machine = excluded.origin_machine, import_digest = coalesce(project_directory.import_digest, excluded.import_digest);
